export function WorkflowAdmin(){
 const [searchParams,setSearchParams]=useSearchParams();
 const [types,setTypes]=useState<any[]>([]),[companies,setCompanies]=useState<any[]>([]);
 const [view,setView]=useState<'list'|'create'|'edit'>('list'),[section,setSection]=useState<'meta'|'requester'|'stages'|'validation'|'publish'>('meta');
 const [typeId,setTypeId]=useState(''),[type,setType]=useState<any>(null),[typeForm,setTypeForm]=useState(emptyType),[allowedSubmitters,setAllowedSubmitters]=useState<string[]>(['company_admin']);
 const [stages,setStages]=useState<Stage[]>([]),[fields,setFields]=useState<Field[]>([]),[questions,setQuestions]=useState<Question[]>([]),[transitions,setTransitions]=useState<Transition[]>([]),[workflowStatus,setWorkflowStatus]=useState('draft'),[draftWorkflowId,setDraftWorkflowId]=useState('');
 const [activeStageId,setActiveStageId]=useState(''),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState(''),[search,setSearch]=useState('');
 const [publishOpen,setPublishOpen]=useState(false),[publishSelection,setPublishSelection]=useState<string[]>([]);

 async function load(){setLoading(true);setError('');try{const [t,c]=await Promise.all([api<any>('/api/workflows/admin/types'),api<any>('/api/workflows/admin/companies')]);setTypes(t.items||[]);setCompanies(c.items||[]);}catch{setError('تعذر تحميل استوديو سير العمل.')}finally{setLoading(false)}}
 useEffect(()=>{void load()},[]);
 useEffect(()=>{const id=searchParams.get('typeId');const isNew=searchParams.get('new')==='1';if(id){void openType(id,(searchParams.get('section') as any)||'meta')}else if(isNew){resetEditor();setView('create');setSection('meta')}else{setView('list');setTypeId('')}},[searchParams]);

 function resetEditor(){setTypeId('');setType(null);setTypeForm({...emptyType});setAllowedSubmitters(['company_admin']);setStages([]);setFields([]);setQuestions([]);setTransitions([]);setDraftWorkflowId('');setActiveStageId('');setWorkflowStatus('draft');setPublishOpen(false);setPublishSelection([]);}
 function goList(){resetEditor();setSearchParams({});}

 async function openType(id:string,initialSection:'meta'|'requester'|'stages'|'validation'|'publish'='meta'){
   setBusy(true);setError('');setMessage('');
   try{
     const meta=await api<any>(`/api/workflows/admin/types/${id}`);const wf=meta.workflow?.find((x:any)=>x.status==='draft')||meta.workflow?.find((x:any)=>x.status==='active')||meta.workflow?.[0];
     setTypeId(id);setType(meta.type);setTypeForm({nameAr:meta.type.name_ar,nameEn:meta.type.name_en||'',description:meta.type.description||'',status:meta.type.status,companyId:null});
     if(wf){
       setWorkflowStatus(wf.status);setDraftWorkflowId(wf.status==='draft'?wf.id:'');
       const d=await api<any>(`/api/workflows/admin/workflows/${wf.id}`);
       const ss=(d.stages||[]).map((x:any)=>({id:x.id,nameAr:x.name_ar,nameEn:x.name_en||'',stageOrder:x.stage_order,responsibleType:x.responsible_type,responsibleValue:x.responsible_value||'',durationMinutes:x.duration_minutes??'',config:x.config||{}}));
       setStages(ss);setActiveStageId(ss[0]?.id||'');setAllowedSubmitters(d.workflow?.allowed_submitters||['company_admin']);
       setFields((d.fields||[]).map((x:any)=>({id:x.id,stageId:x.stage_id||null,fieldKey:x.field_key,labelAr:x.label_ar,labelEn:x.label_en||'',fieldType:x.field_type,required:Boolean(x.required),options:x.options||[],sortOrder:x.sort_order})));
       setQuestions((d.questions||[]).map((x:any)=>({id:x.id,stageId:x.stage_id||null,questionKey:x.question_key,questionAr:x.question_ar,questionEn:x.question_en||'',questionType:x.question_type,required:Boolean(x.required),options:x.options||[],sortOrder:x.sort_order})));
       setTransitions((d.transitions||[]).map((x:any)=>({id:x.id,fromStageId:x.from_stage_id,toStageId:x.to_stage_id||null,action:x.action,labelAr:x.label_ar||'تمرير',condition:x.condition||null,sortOrder:x.sort_order})));
     }else{const first=newStage(1);setWorkflowStatus('draft');setDraftWorkflowId('');setStages([first]);setActiveStageId(first.id);setFields([]);setQuestions([]);setTransitions([]);}
     setView('edit');setSection(initialSection);
   }catch{setError('تعذر تحميل تعريف المعاملة.')}finally{setBusy(false)}
 }

 async function createType(){
   if(typeForm.nameAr.trim().length<2){setError('اكتب اسم المعاملة أولًا.');return}
   setBusy(true);setError('');
   try{
     const d=await api<any>('/api/workflows/admin/types',{method:'POST',body:JSON.stringify({...typeForm,companyId:null,status:'active'})});
     const first=newStage(1);
     const w=await api<any>('/api/workflows/admin/workflows',{method:'POST',body:JSON.stringify({transactionTypeId:d.id,status:'draft',description:typeForm.description||null,allowedSubmitters,stages:[{...first,active:true,durationMinutes:null}],fields:[],questions:[],transitions:[]})});
     setDraftWorkflowId(w.id);setTypeId(d.id);setType({id:d.id,name_ar:typeForm.nameAr,status:'active'});setStages([first]);setActiveStageId(first.id);setFields([]);setQuestions([]);setTransitions([]);setWorkflowStatus('draft');await load();setSearchParams({typeId:d.id,section:'requester'});setView('edit');setSection('requester');setMessage('تم إنشاء القالب. الآن صمّم بيانات مقدم الطلب ثم ابنِ المراحل.');
   }catch(e){setError(e instanceof Error?e.message:'تعذر إنشاء المعاملة.')}finally{setBusy(false)}
 }

 const stageOptions=useMemo(()=>stages.slice().sort((a,b)=>a.stageOrder-b.stageOrder),[stages]);
 const currentStage=stageOptions.find(s=>s.id===activeStageId)||stageOptions[0];
 const requesterFields=fields.filter(f=>f.stageId===null).sort((a,b)=>a.sortOrder-b.sortOrder);
 const requesterQuestions=questions.filter(q=>q.stageId===null).sort((a,b)=>a.sortOrder-b.sortOrder);
 const currentFields=fields.filter(f=>f.stageId===currentStage?.id).sort((a,b)=>a.sortOrder-b.sortOrder);
 const currentQuestions=questions.filter(q=>q.stageId===currentStage?.id).sort((a,b)=>a.sortOrder-b.sortOrder);
 const currentTransitions=transitions.filter(t=>t.fromStageId===currentStage?.id).sort((a,b)=>a.sortOrder-b.sortOrder);
 const priorStages=stageOptions.filter(s=>s.stageOrder<(currentStage?.stageOrder||1));

 function automaticRoutes(ss:Stage[],ts:Transition[]){
   const out=ts.map(x=>({...x}));const sorted=ss.slice().sort((a,b)=>a.stageOrder-b.stageOrder);
   sorted.forEach((st,i)=>{if(i===sorted.length-1)return;const next=sorted[i+1];const outgoing=out.filter(t=>t.fromStageId===st.id);const unconditional=outgoing.find(t=>t.action==='next'&&!t.condition);if(!unconditional){const empty=outgoing.find(t=>t.action==='next'&&!t.toStageId&&!t.condition);if(empty)empty.toStageId=next.id;else out.push({id:uid(),fromStageId:st.id,toStageId:next.id,action:'next',labelAr:'تمرير',condition:null,sortOrder:outgoing.length});}else if(!unconditional.toStageId)unconditional.toStageId=next.id;});return out.map((t,i)=>({...t,sortOrder:i}));
 }
 const normalizedTransitions=useMemo(()=>automaticRoutes(stageOptions,transitions),[stageOptions,transitions]);
 const sourceOptions=useMemo(()=>{
   const stageOrder=(id:string|null)=>stageOptions.find(s=>s.id===id)?.stageOrder||999;
   return [
    ...requesterFields.map(f=>({key:`field.${f.fieldKey}`,label:f.labelAr,group:'مقدم الطلب',type:f.fieldType,options:f.options})),
    ...requesterQuestions.map(q=>({key:`question.${q.questionKey}`,label:q.questionAr,group:'أسئلة مقدم الطلب',type:q.questionType,options:q.options})),
    ...fields.filter(f=>f.stageId&&stageOrder(f.stageId)<=(currentStage?.stageOrder||1)).map(f=>({key:`field.${f.fieldKey}`,label:f.labelAr,group:`المرحلة ${stageOrder(f.stageId)}`,type:f.fieldType,options:f.options})),
    ...questions.filter(q=>q.stageId&&stageOrder(q.stageId)<=(currentStage?.stageOrder||1)).map(q=>({key:`question.${q.questionKey}`,label:q.questionAr,group:`المرحلة ${stageOrder(q.stageId)}`,type:q.questionType,options:q.options}))
   ];
 },[requesterFields,requesterQuestions,fields,questions,currentStage,stageOptions]);

 function addField(stageId:string|null){const list=fields.filter(f=>f.stageId===stageId);const field:Field={id:uid(),stageId,fieldKey:`${stageId?'stage':'request'}_field_${list.length+1}`,labelAr:stageId?'حقل جديد':'عنصر جديد',labelEn:'',fieldType:'text',required:false,options:[],sortOrder:list.length};setFields(v=>[...v,field]);}
 function addQuestion(stageId:string|null){const list=questions.filter(q=>q.stageId===stageId);const q:Question={id:uid(),stageId,questionKey:`${stageId?'stage':'request'}_question_${list.length+1}`,questionAr:'سؤال جديد',questionEn:'',questionType:'yes_no',required:false,options:[],sortOrder:list.length};setQuestions(v=>[...v,q]);}
 function addTransition(){if(!currentStage)return;const t:Transition={id:uid(),fromStageId:currentStage.id,toStageId:stageOptions.find(s=>s.stageOrder===currentStage.stageOrder+1)?.id||null,action:stageOptions.find(s=>s.stageOrder===currentStage.stageOrder+1)?'next':'complete',labelAr:stageOptions.find(s=>s.stageOrder===currentStage.stageOrder+1)?'تمرير':'إكمال المعاملة',condition:{source:'',operator:'equals',value:''},sortOrder:currentTransitions.length};setTransitions(v=>[...v,t]);}
 function addStage(){const s=newStage(stageOptions.length+1);setStages(v=>[...v,s]);setActiveStageId(s.id);setSection('stages');}
 function updateStage(id:string,patch:any){setStages(v=>v.map(s=>s.id===id?{...s,...patch}:s));}
 function moveItem<T extends {id:string;stageId:string|null;sortOrder:number}>(items:T[],id:string,delta:number,scope:string|null){const scoped=items.filter(x=>x.stageId===scope).sort((a,b)=>a.sortOrder-b.sortOrder);const i=scoped.findIndex(x=>x.id===id),j=i+delta;if(i<0||j<0||j>=scoped.length)return items;const copy=scoped.slice();[copy[i],copy[j]]=[copy[j],copy[i]];const order=new Map(copy.map((x,k)=>[x.id,k]));return items.map(x=>x.stageId===scope?{...x,sortOrder:order.get(x.id)??x.sortOrder}:x);}
 function updateCondition(id:string,condition:any){setTransitions(v=>v.map(t=>t.id===id?{...t,condition}:t));}

 function validate(){
   const issues:any[]=[];
   if(typeForm.nameAr.trim().length<2)issues.push({level:'error',title:'اسم المعاملة مفقود',detail:'أضف اسمًا واضحًا للمعاملة.',section:'meta'});
   if(!stageOptions.length)issues.push({level:'error',title:'لا توجد مراحل',detail:'أضف مرحلة واحدة على الأقل.',section:'stages'});
   stageOptions.forEach(s=>{if(!s.nameAr.trim()||s.nameAr.trim().length<2)issues.push({level:'error',title:`اسم المرحلة ${s.stageOrder} غير مكتمل`,detail:'أدخل اسمًا واضحًا للمرحلة.',section:'stages',stageId:s.id});if(!s.responsibleType)issues.push({level:'error',title:`المسؤول غير محدد في المرحلة ${s.stageOrder}`,detail:'حدد نوع المسؤول.',section:'stages',stageId:s.id});});
   const keys=new Set<string>();[...requesterFields,...fields.filter(f=>f.stageId)].forEach(f=>{if(keys.has(f.fieldKey))issues.push({level:'error',title:`المعرف ${f.fieldKey} مكرر`,detail:'غيّر معرف العنصر ليكون فريدًا.',section:f.stageId?'stages':'requester'});keys.add(f.fieldKey);if(['select','multiselect'].includes(f.fieldType)&&!f.options.length)issues.push({level:'error',title:`القائمة «${f.labelAr}» بلا خيارات`,detail:'أضف الخيارات كسطور منفصلة.',section:f.stageId?'stages':'requester'});});
   [...requesterQuestions,...questions.filter(q=>q.stageId)].forEach(q=>{if(['select'].includes(q.questionType)&&!q.options.length)issues.push({level:'error',title:`السؤال «${q.questionAr}» بلا خيارات`,detail:'أضف خيارات الإجابة.',section:q.stageId?'stages':'requester'});});
   currentTransitions.forEach(t=>{if(t.condition&&(!t.condition.source||t.condition.value===''||t.condition.value===undefined)&&!['is_true','is_false'].includes(t.condition.operator))issues.push({level:'error',title:'شرط غير مكتمل',detail:'حدد الحقل والقيمة قبل الحفظ.',section:'stages',stageId:currentStage?.id});if(['next','return'].includes(t.action)&&!t.toStageId)issues.push({level:'error',title:'وجهة الانتقال مفقودة',detail:'اختر المرحلة التي ستذهب إليها المعاملة.',section:'stages',stageId:currentStage?.id});});
   return issues;
 }
 const allIssues=useMemo(()=>{
   const issues:any[]=[];
   if(typeForm.nameAr.trim().length<2)issues.push({level:'error',title:'اسم المعاملة مفقود',detail:'أضف اسمًا واضحًا للمعاملة.',section:'meta'});
   if(!stageOptions.length)issues.push({level:'error',title:'لا توجد مراحل',detail:'أضف مرحلة واحدة على الأقل.',section:'stages'});
   if(!requesterFields.length&&!requesterQuestions.length)issues.push({level:'warning',title:'المعاملة لا تطلب بيانات من مقدم الطلب',detail:'قد يكون هذا صحيحًا لبعض المعاملات، لكن راجع أنك لا تحتاج بيانات بداية الطلب.',section:'requester'});
   const keys=new Set<string>();
   [...fields,...questions].forEach((x:any)=>{const key=x.fieldKey||x.questionKey;if(keys.has(key))issues.push({level:'error',title:`المعرف ${key} مكرر`,detail:'كل عنصر يحتاج معرفًا فريدًا.',section:x.stageId?'stages':'requester',stageId:x.stageId||undefined});keys.add(key);});
   stageOptions.forEach((st:any)=>{
     if(!st.nameAr.trim())issues.push({level:'error',title:`اسم المرحلة ${st.stageOrder} غير مكتمل`,detail:'أدخل اسمًا واضحًا.',section:'stages',stageId:st.id});
     if(!st.responsibleType)issues.push({level:'error',title:`المسؤول غير محدد في «${st.nameAr||`المرحلة ${st.stageOrder}`}»`,detail:'حدد نوع المسؤول.',section:'stages',stageId:st.id});
     if(st.durationMinutes==='')issues.push({level:'warning',title:`مدة «${st.nameAr||`المرحلة ${st.stageOrder}`}» غير محددة`,detail:'يمكن تركها بلا مدة، لكن لن يظهر استحقاق زمني لهذه المرحلة.',section:'stages',stageId:st.id});
     const sf=fields.filter((f:any)=>f.stageId===st.id),sq=questions.filter((q:any)=>q.stageId===st.id);
     if(!sf.length&&!sq.length)issues.push({level:'warning',title:`«${st.nameAr||`المرحلة ${st.stageOrder}`}» بلا بيانات`,detail:'أضف حقلًا أو سؤالًا إذا كان المسؤول يحتاج تنفيذًا أو قرارًا.',section:'stages',stageId:st.id});
     [...sf,...fields.filter((f:any)=>f.stageId===null)].forEach((f:any)=>{if(['select','multiselect'].includes(f.fieldType)&&!f.options.length)issues.push({level:'error',title:`القائمة «${f.labelAr}» بلا خيارات`,detail:'أضف الخيارات كسطور منفصلة.',section:f.stageId?'stages':'requester',stageId:f.stageId||undefined});});
     [...sq,...questions.filter((q:any)=>q.stageId===null)].forEach((q:any)=>{if(q.questionType==='select'&&!q.options.length)issues.push({level:'error',title:`السؤال «${q.questionAr}» بلا خيارات`,detail:'أضف خيارات الإجابة.',section:q.stageId?'stages':'requester',stageId:q.stageId||undefined});});
   });
   normalizedTransitions.filter((t:any)=>t.fromStageId===activeStageId).forEach((t:any)=>{if(t.condition&&(!t.condition.source||((t.condition.value===''||t.condition.value===undefined)&&!['is_true','is_false'].includes(t.condition.operator))))issues.push({level:'error',title:'شرط غير مكتمل',detail:'حدد الحقل والقيمة قبل النشر.',section:'stages',stageId:activeStageId});if(['next','return'].includes(t.action)&&!t.toStageId&&t.condition)issues.push({level:'error',title:'وجهة الانتقال مفقودة',detail:'حدد المرحلة التي سيذهب إليها هذا الفرع.',section:'stages',stageId:activeStageId});});
   return issues;
 },[typeForm,stageOptions,fields,questions,requesterFields,requesterQuestions,normalizedTransitions,activeStageId]);

 async function saveWorkflow(status=workflowStatus){
   if(!draftWorkflowId){setError('لا توجد مسودة Workflow للحفظ.');return false}
   const issues=allIssues.filter((x:any)=>x.level==='error');if(issues.length){setError(issues[0].title+' — '+issues[0].detail);setSection(issues[0].section);if(issues[0].stageId)setActiveStageId(issues[0].stageId);return false}
   setBusy(true);setError('');
   try{await api(`/api/workflows/admin/workflows/${draftWorkflowId}`,{method:'PATCH',body:JSON.stringify({transactionTypeId:typeId,description:typeForm.description||null,allowedSubmitters,status,stages:stageOptions.map(s=>({...s,active:true,durationMinutes:s.durationMinutes===''?null:s.durationMinutes})),fields,questions,transitions:automaticRoutes(stageOptions,transitions)})});setWorkflowStatus(status);setMessage(status==='active'?'تم نشر الإصدار الحالي كنسخة نشطة.':'تم حفظ المسودة بنجاح.');return true;}catch(e){setError(e instanceof Error?e.message:'تعذر حفظ Workflow.');return false}finally{setBusy(false)}
 }
 async function saveTypeMeta(){setBusy(true);setError('');try{await api(`/api/workflows/admin/types/${typeId}`,{method:'PATCH',body:JSON.stringify({nameAr:typeForm.nameAr,nameEn:typeForm.nameEn||null,description:typeForm.description||null,status:typeForm.status})});setMessage('تم حفظ بيانات المعاملة.');return true;}catch(e){setError(e instanceof Error?e.message:'تعذر حفظ بيانات المعاملة.');return false}finally{setBusy(false)}}
 async function startDraftEdit(){
   if(draftWorkflowId)return true;
   setBusy(true);setError('');
   try{const d=await api<any>('/api/workflows/admin/workflows',{method:'POST',body:JSON.stringify({transactionTypeId:typeId,status:'draft',description:typeForm.description||null,allowedSubmitters,stages:stageOptions.map(s=>({...s,active:true,durationMinutes:s.durationMinutes===''?null:s.durationMinutes})),fields,questions,transitions:automaticRoutes(stageOptions,transitions)})});setDraftWorkflowId(d.id);setWorkflowStatus('draft');setMessage('تم إنشاء مسودة تعديل جديدة. النسخة المنشورة والمعاملات السابقة لن تتأثر.');return true;}catch(e){setError(e instanceof Error?e.message:'تعذر إنشاء مسودة التعديل.');return false}finally{setBusy(false)}}
 async function saveAll(){const ok=await saveTypeMeta();if(!ok)return false;if(!draftWorkflowId){const created=await startDraftEdit();if(!created)return false;}return await saveWorkflow('draft');}
 async function publish(){if(!publishSelection.length){setError('اختر شركة واحدة على الأقل للنشر.');return}setBusy(true);setError('');try{await saveWorkflow('draft');const d=await api<any>(`/api/workflows/admin/types/${typeId}/publish`,{method:'POST',body:JSON.stringify({companyIds:publishSelection})});setPublishOpen(false);setMessage(`تم نشر القالب إلى ${d.results?.filter((x:any)=>x.status!=='exists').length??publishSelection.length} شركة.`);await load();}catch(e){setError(e instanceof Error?e.message:'تعذر نشر المعاملة للشركات.')}finally{setBusy(false)}}
 async function activate(){setBusy(true);setError('');try{await api(`/api/workflows/admin/types/${typeId}/activate-draft`,{method:'POST'});setWorkflowStatus('active');setDraftWorkflowId('');setMessage('تم تفعيل النسخة الحالية. ولأي تعديل لاحق ستنشئ مسودة إصدار جديدة.');await load();}catch(e){setError(e instanceof Error?e.message:'تعذر تفعيل النسخة.')}finally{setBusy(false)}}
 async function clearStudio(){
   const ok=window.confirm('سيتم حذف كل قوالب المعاملات ومسوداتها ونسخ الشركات والمعاملات وبيانات الاختبار وتسلسلات الأرقام الخاصة بـ Phase 6. لن تُحذف الشركات أو الموظفون أو المستخدمون أو الصلاحيات. هذا الإجراء نهائي. هل تريد تصفير الاستوديو بالكامل؟');if(!ok)return;
   setBusy(true);setError('');try{const d=await api<any>('/api/workflows/admin/transactions/clear',{method:'POST',body:JSON.stringify({resetStudio:true})});try{localStorage.removeItem(STORAGE_KEY);Object.keys(localStorage).filter(k=>k.startsWith('hrnexus.workflowDraftStep:')).forEach(k=>localStorage.removeItem(k));}catch{}resetEditor();await load();setMessage(`تم تصفير استوديو المعاملات بالكامل. حُذف ${Number(d.deletedTypes||0)} قالبًا و${Number(d.deletedTransactions||0)} معاملة.`);setSearchParams({});}catch(e){setError(e instanceof Error?e.message:'تعذر تصفير الاستوديو.')}finally{setBusy(false)}}

 if(loading&&!types.length)return <div className="panel-empty">جاري تحميل استوديو سير العمل...</div>;
 if(view==='list')return <StudioHome types={types} search={search} setSearch={setSearch} openType={openType} createNew={()=>{resetEditor();setSearchParams({new:'1'});setView('create')}} clearStudio={clearStudio} busy={busy} error={error} message={message} />;
 if(view==='create')return <CreateTypePage typeForm={typeForm} setTypeForm={setTypeForm} allowedSubmitters={allowedSubmitters} setAllowedSubmitters={setAllowedSubmitters} createType={createType} goList={goList} busy={busy} error={error} />;
 return <StudioEditor type={type} typeForm={typeForm} setTypeForm={setTypeForm} allowedSubmitters={allowedSubmitters} setAllowedSubmitters={setAllowedSubmitters} section={section} setSection={setSection} stages={stageOptions} activeStageId={activeStageId} setActiveStageId={setActiveStageId} fields={fields} setFields={setFields} questions={questions} setQuestions={setQuestions} transitions={normalizedTransitions} rawTransitions={transitions} setTransitions={setTransitions} requesterFields={requesterFields} requesterQuestions={requesterQuestions} currentStage={currentStage} currentFields={currentFields} currentQuestions={currentQuestions} currentTransitions={normalizedTransitions.filter(t=>t.fromStageId===currentStage?.id)} priorStages={priorStages} sourceOptions={sourceOptions} addField={addField} addQuestion={addQuestion} addTransition={addTransition} addStage={addStage} updateStage={updateStage} moveItem={moveItem} updateCondition={updateCondition} saveAll={saveAll} startDraftEdit={startDraftEdit} saveWorkflow={saveWorkflow} saveTypeMeta={saveTypeMeta} publish={()=>setPublishOpen(true)} activate={activate} busy={busy} error={error} message={message} goList={goList} workflowStatus={workflowStatus} draftWorkflowId={draftWorkflowId} allIssues={allIssues} publishOpen={publishOpen} setPublishOpen={setPublishOpen} publishSelection={publishSelection} setPublishSelection={setPublishSelection} companies={companies} publishNow={publish} typeId={typeId} />;
}

function StudioHome({types,search,setSearch,openType,createNew,clearStudio,busy,error,message}:{types:any[];search:string;setSearch:(v:string)=>void;openType:(id:string)=>void;createNew:()=>void;clearStudio:()=>void;busy:boolean;error:string;message:string}){
 const templates=types.filter(x=>(`${x.name_ar||''} ${x.name_en||''}`).toLowerCase().includes(search.toLowerCase()));
 const drafts=types.filter(x=>x.workflow_status==='draft').length,active=types.filter(x=>x.workflow_status==='active').length;
 return <div className="studio-v13">
  <div className="studio-hero-v13"><div><div className="eyebrow">إدارة المنصة · استوديو سير العمل</div><h1>ابنِ المعاملة مرة، وشغّلها بثقة.</h1><p>صمّم القالب، اربط مقدم الطلب بالمعلومات التي يحتاجها، ابنِ المراحل ومساراتها، ثم اختبره وانشر نسخة مستقلة لكل شركة.</p></div><div className="hero-actions-v13"><button className="btn primary" onClick={createNew}>+ إنشاء معاملة</button><Link className="btn secondary" to="/platform/workflows/test"><PlayCircle size={16}/>بيئة الاختبار</Link></div></div>
  <div className="studio-commandbar"><div className="studio-stat"><strong>{types.length}</strong><span>قوالب</span></div><div className="studio-stat"><strong>{drafts}</strong><span>مسودات</span></div><div className="studio-stat"><strong>{active}</strong><span>نسخ نشطة</span></div><div className="studio-command-spacer"/><button className="btn danger" disabled={busy} onClick={clearStudio}><RotateCcw size={15}/>تصفير الاستوديو</button></div>
  {message&&<div className="studio-alert success"><Check size={17}/>{message}</div>}{error&&<div className="studio-alert error"><X size={17}/>{error}</div>}
  <section className="studio-section-v13"><div className="section-head-v13"><div><span>قوالب المعاملات</span><h2>مكتبة القوالب</h2><p>كل بطاقة تمثل تعريفًا مستقلًا للمعاملة. افتحها لتعديلها أو اختبارها أو نشرها.</p></div><div className="studio-search"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="ابحث باسم المعاملة..."/></div></div>
   {templates.length===0?<div className="empty-studio-v13"><LayoutTemplate size={34}/><strong>الاستوديو جاهز لبداية جديدة</strong><span>لا توجد قوالب مطابقة. أنشئ أول معاملة ثم ابنِها خطوة بخطوة.</span><button className="btn primary" onClick={createNew}>إنشاء أول معاملة</button></div>:<div className="template-grid-v13">{templates.map((x:any)=><article className="template-card-v13" key={x.id}><div className="template-card-top"><div className="template-icon-v13"><Zap size={18}/></div><span className={`status-pill ${x.workflow_status==='active'?'active':x.workflow_status==='draft'?'draft':'muted'}`}>{x.workflow_status==='active'?'نشط':x.workflow_status==='draft'?'مسودة':'غير نشط'}</span></div><h3>{x.name_ar}</h3><p>{x.description||'لا يوجد وصف. افتح القالب لإضافة وصف واضح يساعد مسؤولي النظام.'}</p><div className="template-meta-v13"><span>الإصدار {x.workflow_version||'—'}</span><span>{x.workflow_count||0} تعريف</span></div><div className="template-actions-v13"><button className="btn primary" onClick={()=>openType(x.id)}><Settings2 size={15}/>تعديل المعاملة</button><Link className="btn secondary" to={`/platform/workflows/test/${x.id}`}><PlayCircle size={15}/>اختبار</Link></div></article>)}</div>}
  </section>
 </div>
}


function CreateTypePage(p:any){
 const submitters=[['company_admin','مدير الشركة'],['role:hr','دور الموارد البشرية'],['permission:transaction.create','من يملك صلاحية إنشاء المعاملة']];
 return <div className="studio-v13 create-v13"><div className="editor-top-v13"><div><button className="back-link-v13" onClick={p.goList}><ArrowRight size={15}/>قوالب المعاملات</button><div className="eyebrow">استوديو سير العمل · إنشاء قالب</div><h1>أنشئ تعريف المعاملة</h1><p>نبدأ بالمعلومات الأساسية فقط. بعد الحفظ ستدخل مباشرة إلى مصمم مقدم الطلب ثم المراحل.</p></div></div>{p.error&&<div className="studio-alert error"><X size={17}/>{p.error}</div>}<div className="create-type-layout-v13"><section className="form-card-v13"><SectionIntro number="01" title="بيانات المعاملة" text="اسم واضح، وصف اختياري، ومن يملك صلاحية بدء المعاملة."/><label className="form-field"><span>اسم المعاملة *</span><input autoFocus value={p.typeForm.nameAr} onChange={e=>p.setTypeForm({...p.typeForm,nameAr:e.target.value})} placeholder="مثال: طلب تعديل راتب"/></label><label className="form-field"><span>الوصف <small>(اختياري)</small></span><textarea rows={5} value={p.typeForm.description} onChange={e=>p.setTypeForm({...p.typeForm,description:e.target.value})} placeholder="اكتب جملة أو جملتين تشرحان متى تستخدم المعاملة."/></label><div className="subhead-v13"><div><span>من يستطيع تقديمها؟</span><strong>صلاحية البداية</strong></div></div><div className="choice-grid-v13">{submitters.map(([v,l])=><label className={`choice-card-v13 ${p.allowedSubmitters.includes(v)?'selected':''}`} key={v}><input type="checkbox" checked={p.allowedSubmitters.includes(v)} onChange={e=>p.setAllowedSubmitters((x:string[])=>e.target.checked?[...new Set([...x,v])]:x.filter(y=>y!==v))}/><span><strong>{l}</strong><small>يمكن تعديل هذه القائمة لاحقًا</small></span><Check size={16}/></label>)}</div><div className="insight-card-v13"><Zap size={18}/><div><strong>قاعدة الموظف</strong><p>المعاملة تخص مقدم الطلب افتراضيًا. إذا احتجت أن يحدد مقدم الطلب موظفًا آخر، ستضيف «الموظف المعني» في الخطوة التالية.</p></div></div><button className="btn primary wide-v13" disabled={p.busy} onClick={p.createType}><Plus size={16}/>إنشاء القالب والانتقال إلى مقدم الطلب</button></section><aside className="create-preview-v13"><div className="preview-kicker">نموذج القالب</div><div className="create-preview-icon"><LayoutTemplate size={24}/></div><h3>{p.typeForm.nameAr||'اسم المعاملة'}</h3><p>{p.typeForm.description||'وصف المعاملة سيظهر هنا عند إضافته.'}</p><div><span>الخطوة التالية</span><strong>مقدم الطلب</strong></div><div><span>بعدها</span><strong>المراحل والمسارات</strong></div></aside></div></div>
}

function StudioEditor(p:any){
 const sectionLabels:any={meta:'بيانات المعاملة',requester:'مقدم الطلب',stages:'المراحل',validation:'التحقق والمعاينة',publish:'النشر للشركات'};
 const stepIndex=['meta','requester','stages','validation','publish'].indexOf(p.section);
 return <div className="studio-v13 editor-v13">
  <div className="editor-top-v13"><div><button className="back-link-v13" onClick={p.goList}><ArrowRight size={15}/>قوالب المعاملات</button><div className="eyebrow">استوديو سير العمل · محرر القالب</div><div className="editor-title-line"><h1>{p.typeForm.nameAr||'معاملة جديدة'}</h1><span className={`status-pill ${p.workflowStatus==='active'?'active':'draft'}`}>{p.workflowStatus==='active'?'نشط':'مسودة'}</span></div><p>هذا القالب مستقل عن الشركات حتى يتم نشره. أي تعديل هنا لا يغيّر معاملات الشركات القائمة.</p></div><div className="editor-actions-v13"><Link className="btn secondary" to={`/platform/workflows/test/${p.typeId}`}><PlayCircle size={16}/>اختبار القالب</Link>{!p.draftWorkflowId&&<button className="btn secondary" disabled={p.busy} onClick={p.startDraftEdit}><Copy size={16}/>إنشاء مسودة تعديل</button>}<button className="btn secondary" disabled={p.busy} onClick={p.saveAll}><Save size={16}/>حفظ</button><button className="btn primary" disabled={p.busy} onClick={()=>p.setSection('publish')}><Send size={16}/>النشر للشركات</button></div></div>
  {p.message&&<div className="studio-alert success"><Check size={17}/>{p.message}</div>}{p.error&&<div className="studio-alert error"><X size={17}/>{p.error}</div>}
  <div className="editor-shell-v13"><aside className="editor-nav-v13"><div className="editor-nav-title"><span>بناء المعاملة</span><strong>الخطوات</strong></div>{[['meta','01','بيانات المعاملة'],['requester','02','مقدم الطلب'],['stages','03','المراحل'],['validation','04','التحقق والمعاينة'],['publish','05','النشر للشركات']].map(([id,num,label])=><button key={id} className={`editor-nav-item ${p.section===id?'active':''}`} onClick={()=>p.setSection(id)}><b>{num}</b><span>{label}</span>{p.section===id&&<ChevronLeft size={15}/>}</button>)}<div className="editor-nav-tip"><ShieldCheck size={16}/><span>المعاملات الفعلية تستخدم النسخة المنشورة للشركة. الاختبار هنا لا ينشئ سجلًا حقيقيًا.</span></div></aside>
   <main className="editor-content-v13">{p.section==='meta'&&<MetaSection {...p}/>} {p.section==='requester'&&<RequesterSection {...p}/>} {p.section==='stages'&&<StagesSection {...p}/>} {p.section==='validation'&&<ValidationSection {...p}/>} {p.section==='publish'&&<PublishSection {...p}/>}</main>
  </div>
  <div className="editor-footer-v13"><div><span>الخطوة {stepIndex+1} من 5</span><strong>{sectionLabels[p.section]}</strong></div><div className="footer-progress-v13"><i style={{width:`${((stepIndex+1)/5)*100}%`}}/></div><div className="footer-buttons-v13">{stepIndex>0&&<button className="btn secondary" onClick={()=>p.setSection(['meta','requester','stages','validation','publish'][stepIndex-1])}>السابق</button>}{stepIndex<4&&<button className="btn primary" onClick={async()=>{await p.saveAll();p.setSection(['meta','requester','stages','validation','publish'][stepIndex+1])}}>حفظ ومتابعة <ChevronLeft size={15}/></button>}</div></div>
  {p.publishOpen&&<PublishModal {...p}/>} 
 </div>
}

function MetaSection(p:any){const submitterOptions=[['company_admin','مدير الشركة'],['role:hr','دور الموارد البشرية'],['permission:transaction.create','من يملك صلاحية إنشاء المعاملة'],['manager','المدير المباشر']];return <div className="editor-section-v13"><SectionIntro number="01" title="بيانات المعاملة" text="عرّف هوية المعاملة ومن يملك حق بدءها. أبقينا هذه الصفحة خفيفة لأن التفاصيل تأتي في الخطوات التالية."/><div className="form-card-v13"><div className="field-grid-v13 two"><label className="form-field"><span>اسم المعاملة *</span><input value={p.typeForm.nameAr} onChange={e=>p.setTypeForm({...p.typeForm,nameAr:e.target.value})} placeholder="مثال: طلب تعديل راتب"/></label><label className="form-field"><span>الاسم بالإنجليزية <small>(اختياري)</small></span><input value={p.typeForm.nameEn} onChange={e=>p.setTypeForm({...p.typeForm,nameEn:e.target.value})} placeholder="Salary Adjustment Request"/></label></div><label className="form-field"><span>وصف المعاملة <small>(اختياري)</small></span><textarea rows={4} value={p.typeForm.description} onChange={e=>p.setTypeForm({...p.typeForm,description:e.target.value})} placeholder="متى تستخدم هذه المعاملة؟ وما الغرض منها؟"/></label></div><div className="form-card-v13"><div className="subhead-v13"><div><span>من يستطيع تقديم المعاملة؟</span><strong>صلاحية البدء</strong><p>حدد الجهات التي يمكنها فتح معاملة جديدة من هذا القالب.</p></div><Users size={20}/></div><div className="choice-grid-v13">{submitterOptions.map(([value,label])=><label className={`choice-card-v13 ${p.allowedSubmitters.includes(value)?'selected':''}`} key={value}><input type="checkbox" checked={p.allowedSubmitters.includes(value)} onChange={e=>p.setAllowedSubmitters((v:string[])=>e.target.checked?[...new Set([...v,value])]:v.filter(x=>x!==value))}/><span><strong>{label}</strong><small>{value==='company_admin'?'مدير الشركة':value.startsWith('role:')?'دور محدد':value.startsWith('permission:')?'صلاحية نظام':'مسؤول حسب الهيكل'}</small></span><Check size={16}/></label>)}</div></div><div className="insight-card-v13"><Zap size={18}/><div><strong>قاعدة الموظف المعني</strong><p>افتراضيًا، المعاملة تخص مقدم الطلب نفسه. إذا كانت بعض المعاملات تخص موظفًا آخر، أضف عنصر «الموظف المعني» في خطوة مقدم الطلب وسيظهر للمستخدم كقائمة بحث بالرقم الوظيفي أو الاسم.</p></div></div><button className="btn primary wide-v13" onClick={p.saveAll} disabled={p.busy}><Save size={16}/>حفظ بيانات المعاملة</button></div>}

function RequesterSection(p:any){return <div className="editor-section-v13"><SectionIntro number="02" title="مقدم الطلب" text="هذه هي المعلومات التي يعبئها صاحب المعاملة قبل أن تبدأ المرحلة الأولى. لا نضيف أي عنصر من عندنا."/><div className="requester-layout-v13"><div className="form-card-v13"><div className="subhead-v13"><div><span>عناصر مقدم الطلب</span><strong>بيانات الطلب</strong><p>كل عنصر تضيفه يظهر للمستخدم كما هو، ويمكن ترتيبه بالسهمين.</p></div><button className="btn primary" onClick={()=>p.addField(null)}><Plus size={15}/>إضافة عنصر</button></div>{p.requesterFields.length===0?<EmptyBuilder title="لا توجد عناصر بعد" text="ابدأ بإضافة أول حقل يحتاجه مقدم الطلب." action="إضافة أول عنصر" onClick={()=>p.addField(null)}/>:<div className="builder-stack-v13">{p.requesterFields.map((f:any,i:number)=><FieldRow key={f.id} f={f} index={i} scope={null} {...p}/>)}</div>}</div><div className="form-card-v13"><div className="subhead-v13"><div><span>الأسئلة والقرارات</span><strong>أسئلة مقدم الطلب</strong><p>يجيب عنها مقدم الطلب قبل إرسال المعاملة إلى المرحلة الأولى.</p></div><button className="btn secondary" onClick={()=>p.addQuestion(null)}><Plus size={15}/>إضافة سؤال</button></div>{p.requesterQuestions.length===0?<EmptyBuilder title="لا توجد أسئلة" text="إذا احتاجت المعاملة إجابة قبل بدء سير العمل، أضفها هنا." action="إضافة سؤال" onClick={()=>p.addQuestion(null)}/>:<div className="builder-stack-v13">{p.requesterQuestions.map((q:any,i:number)=><QuestionRow key={q.id} q={q} index={i} scope={null} {...p}/>)}</div>}</div></div><div className="info-banner-v13"><ShieldCheck size={18}/><div><strong>الموظف المعني اختياري</strong><span>الأصل أن المعاملة تخص مقدم الطلب. إذا أضفت عنصر نوعه «الموظف المعني»، يستطيع مقدم الطلب اختيار موظف آخر من قائمة موظفي الشركة بالرقم الوظيفي أو الاسم.</span></div></div></div>}

function StagesSection(p:any){return <div className="editor-section-v13"><SectionIntro number="03" title="المراحل" text="كل مرحلة لها مسؤولها وبياناتها وأسئلتها وقراراتها ومسارها. المرحلة التالية هي المسار التلقائي ما لم تضف شرطًا."/><div className="stage-editor-v13"><aside className="stage-list-v13"><div className="stage-list-head"><div><span>رحلة المعاملة</span><strong>{p.stages.length} مراحل</strong></div><button className="icon-btn" onClick={p.addStage} title="إضافة مرحلة"><Plus size={16}/></button></div>{p.stages.map((s:any)=><button key={s.id} className={`stage-list-item ${p.activeStageId===s.id?'active':''}`} onClick={()=>p.setActiveStageId(s.id)}><b>{s.stageOrder}</b><span><strong>{s.nameAr}</strong><small>{responsibilityLabels[s.responsibleType]||s.responsibleType}</small></span><ChevronLeft size={14}/></button>)}<button className="stage-add-v13" onClick={p.addStage}><Plus size={15}/>إضافة مرحلة</button></aside><div className="stage-workspace-v13">{p.currentStage?<StageEditor {...p}/>:<EmptyBuilder title="أضف أول مرحلة" text="كل معاملة تحتاج مرحلة واحدة على الأقل." action="إضافة مرحلة" onClick={p.addStage}/>}</div></div></div>}

function StageEditor(p:any){const s=p.currentStage;const next=p.stages.find((x:any)=>x.stageOrder===s.stageOrder+1);return <>
 <div className="stage-header-v13"><div><span>المرحلة {s.stageOrder}</span><h2>{s.nameAr}</h2><p>هذه المرحلة تملك بياناتها وأسئلتها وقرارها الخاص.</p></div><div className="stage-header-actions"><button className="btn secondary" onClick={()=>p.addStage()}><Plus size={15}/>مرحلة بعدها</button></div></div>
 <div className="form-card-v13 stage-config-v13"><div className="field-grid-v13 four"><label className="form-field"><span>اسم المرحلة *</span><input value={s.nameAr} onChange={e=>p.updateStage(s.id,{nameAr:e.target.value})}/></label><label className="form-field"><span>المسؤول</span><select value={s.responsibleType} onChange={e=>p.updateStage(s.id,{responsibleType:e.target.value})}>{Object.entries(responsibilityLabels).map(([k,v])=><option key={k} value={k}>{String(v)}</option>)}</select></label><label className="form-field"><span>قيمة المسؤول <small>(عند الحاجة)</small></span><input value={s.responsibleValue} onChange={e=>p.updateStage(s.id,{responsibleValue:e.target.value})} placeholder="مثل معرف الدور أو المنصب"/></label><label className="form-field"><span>مدة المرحلة <small>(اختياري)</small></span><div className="input-with-unit-v13"><input type="number" min={1} value={s.durationMinutes} onChange={e=>p.updateStage(s.id,{durationMinutes:e.target.value===''?'':Number(e.target.value)})}/><span>دقيقة</span></div></label></div><div className="stage-settings-v13"><label><input type="checkbox" checked={Boolean(s.config?.allowAttachments)} onChange={e=>p.updateStage(s.id,{config:{...s.config,allowAttachments:e.target.checked}})}/><span>السماح بمرفقات في هذه المرحلة</span></label>{s.config?.allowAttachments&&<label className="mini-setting"><span>الحد الأقصى</span><input type="number" min={1} value={s.config?.maxAttachments??''} onChange={e=>p.updateStage(s.id,{config:{...s.config,maxAttachments:e.target.value===''?null:Number(e.target.value)}})}/></label>}</div></div>
 {p.priorStages.length>0&&<div className="context-strip-v13"><div><span>السياق الذي يصل إلى هذه المرحلة</span><strong>البيانات السابقة للقراءة</strong></div><div className="context-tags-v13">{p.requesterFields.map((f:any)=><span key={f.id}>مقدم الطلب · {f.labelAr}</span>)}{p.requesterQuestions.map((q:any)=><span key={q.id}>سؤال · {q.questionAr}</span>)}{p.priorStages.map((ps:any)=><span key={ps.id}>المرحلة {ps.stageOrder} · {ps.nameAr}</span>)}</div></div>}
 <BuilderPanel title="بيانات المرحلة" description="الحقول التي يعبئها مسؤول هذه المرحلة." addLabel="إضافة حقل" onAdd={()=>p.addField(s.id)}><div className="builder-stack-v13">{p.currentFields.length===0?<EmptyBuilder title="لا توجد بيانات خاصة بالمرحلة" text="أضف فقط ما يحتاجه مسؤول المرحلة." action="إضافة حقل" onClick={()=>p.addField(s.id)}/>:p.currentFields.map((f:any,i:number)=><FieldRow key={f.id} f={f} index={i} scope={s.id} {...p}/>)}</div></BuilderPanel>
 <BuilderPanel title="الأسئلة والقرارات" description="وحدة واحدة: سؤال المسؤول، وإجابته قد تحدد أثر المعاملة." addLabel="إضافة سؤال" onAdd={()=>p.addQuestion(s.id)}><div className="builder-stack-v13">{p.currentQuestions.length===0?<EmptyBuilder title="لا توجد أسئلة أو قرارات" text="إذا كانت المرحلة تحتاج قرارًا، أضف السؤال هنا." action="إضافة سؤال" onClick={()=>p.addQuestion(s.id)}/>:p.currentQuestions.map((q:any,i:number)=><QuestionRow key={q.id} q={q} index={i} scope={s.id} {...p}/>)}</div></BuilderPanel>
 <BuilderPanel title="المسار" description={next?`الافتراضي: بعد التمرير تنتقل المعاملة إلى «${next.nameAr}». أضف شرطًا فقط عندما تريد نتيجة مختلفة.`:'هذه آخر مرحلة؛ الافتراضي هو إكمال المعاملة.'} addLabel="إضافة شرط" onAdd={p.addTransition} icon={<GitBranch size={15}/>}><RouteBuilder {...p} next={next}/></BuilderPanel>
 </>}

function FieldRow(p:any){const f=p.f;const options=Array.isArray(f.options)?f.options:[];return <div className="builder-row-v13"><div className="row-number-v13">{p.index+1}</div><div className="row-body-v13"><div className="row-grid-v13"><label className="form-field"><span>اسم العنصر</span><input value={f.labelAr} onChange={e=>p.setFields((v:any)=>v.map((x:any)=>x.id===f.id?{...x,labelAr:e.target.value}:x))}/></label><label className="form-field"><span>المعرف</span><input value={f.fieldKey} onChange={e=>p.setFields((v:any)=>v.map((x:any)=>x.id===f.id?{...x,fieldKey:e.target.value}:x))}/></label><label className="form-field"><span>نوع العنصر</span><select value={f.fieldType} onChange={e=>p.setFields((v:any)=>v.map((x:any)=>x.id===f.id?{...x,fieldType:e.target.value}:x))}>{Object.entries(fieldTypes).map(([k,v])=><option key={k} value={k}>{String(v)}</option>)}</select></label><label className="switch-v13"><input type="checkbox" checked={f.required} onChange={e=>p.setFields((v:any)=>v.map((x:any)=>x.id===f.id?{...x,required:e.target.checked}:x))}/><span>مطلوب</span></label></div>{f.fieldType==='employee'&&<div className="field-note-v13"><Users size={14}/> عند الاستخدام، يظهر للمستخدم بحث عن موظف فعلي بالرقم الوظيفي أو الاسم. إذا لم يختَر موظفًا تبقى القاعدة الافتراضية: المعاملة تخص مقدم الطلب.</div>}{['select','multiselect'].includes(f.fieldType)&&<OptionListEditor options={options} onChange={(next:any)=>p.setFields((v:any)=>v.map((x:any)=>x.id===f.id?{...x,options:next}:x))}/>}</div><div className="row-controls-v13"><button className="icon-btn" disabled={p.index===0} onClick={()=>p.setFields((v:any)=>p.moveItem(v,f.id,-1,p.scope))}><ChevronUp size={14}/></button><button className="icon-btn" disabled={p.index===p.fields.filter((x:any)=>x.stageId===p.scope).length-1} onClick={()=>p.setFields((v:any)=>p.moveItem(v,f.id,1,p.scope))}><ChevronDown size={14}/></button><button className="icon-btn danger-icon" onClick={()=>p.setFields((v:any)=>v.filter((x:any)=>x.id!==f.id))}><Trash2 size={15}/></button></div></div>}
function QuestionRow(p:any){const q=p.q;return <div className="builder-row-v13"><div className="row-number-v13">{p.index+1}</div><div className="row-body-v13"><div className="row-grid-v13"><label className="form-field"><span>السؤال</span><input value={q.questionAr} onChange={e=>p.setQuestions((v:any)=>v.map((x:any)=>x.id===q.id?{...x,questionAr:e.target.value}:x))}/></label><label className="form-field"><span>المعرف</span><input value={q.questionKey} onChange={e=>p.setQuestions((v:any)=>v.map((x:any)=>x.id===q.id?{...x,questionKey:e.target.value}:x))}/></label><label className="form-field"><span>نوع الإجابة</span><select value={q.questionType} onChange={e=>p.setQuestions((v:any)=>v.map((x:any)=>x.id===q.id?{...x,questionType:e.target.value}:x))}>{Object.entries(questionTypes).map(([k,v])=><option key={k} value={k}>{String(v)}</option>)}</select></label><label className="switch-v13"><input type="checkbox" checked={q.required} onChange={e=>p.setQuestions((v:any)=>v.map((x:any)=>x.id===q.id?{...x,required:e.target.checked}:x))}/><span>مطلوب</span></label></div>{q.questionType==='select'&&<OptionListEditor options={q.options||[]} onChange={(next:any)=>p.setQuestions((v:any)=>v.map((x:any)=>x.id===q.id?{...x,options:next}:x))}/>}</div><div className="row-controls-v13"><button className="icon-btn" disabled={p.index===0} onClick={()=>p.setQuestions((v:any)=>p.moveItem(v,q.id,-1,p.scope))}><ChevronUp size={14}/></button><button className="icon-btn" disabled={p.index===p.questions.filter((x:any)=>x.stageId===p.scope).length-1} onClick={()=>p.setQuestions((v:any)=>p.moveItem(v,q.id,1,p.scope))}><ChevronDown size={14}/></button><button className="icon-btn danger-icon" onClick={()=>p.setQuestions((v:any)=>v.filter((x:any)=>x.id!==q.id))}><Trash2 size={15}/></button></div></div>}
function OptionListEditor({options,onChange}:{options:any[];onChange:(x:any[])=>void}){return <div className="options-editor-v13"><div><strong>خيارات القائمة</strong><span>أضف كل قيمة في سطر مستقل.</span></div>{options.map((o:any,i:number)=><div className="option-row-v13" key={i}><span>{i+1}</span><input value={optionLabel(o)} onChange={e=>onChange(options.map((x:any,k:number)=>k===i?e.target.value:x))}/><button className="icon-btn danger-icon" onClick={()=>onChange(options.filter((_:any,k:number)=>k!==i))}><X size={14}/></button></div>)}<button className="btn ghost" onClick={()=>onChange([...options,''])}><Plus size={14}/>إضافة خيار</button></div>}

function RouteBuilder(p:any){const next=p.next;const routes=p.currentTransitions.filter((t:any)=>!(t.action==='next'&&!t.condition&&t.toStageId===next?.id));return <div className="route-builder-v13">{next&&<div className="default-route-v13"><div className="route-icon-v13"><Zap size={16}/></div><div><strong>المسار التلقائي</strong><span>تمرير المعاملة → {next.nameAr}</span></div><em>تلقائي</em></div>}{p.currentTransitions.filter((t:any)=>t.condition||t.action!=='next'||t.toStageId!==next?.id).map((t:any)=><ConditionRoute key={t.id} t={t} {...p}/>)}{!routes.length&&<div className="route-empty-v13">لا توجد شروط إضافية. اترك المسار التلقائي يعمل أو أضف شرطًا إذا احتاجت المعاملة تفرعًا.</div>}</div>}
function ConditionRoute(p:any){const t=p.t;const o=p.sourceOptions.find((x:any)=>x.key===t.condition?.source);const terminal=['complete','reject','cancel'].includes(t.action);return <div className="condition-route-v13"><div className="condition-head-v13"><span>شرط انتقال</span><button className="icon-btn danger-icon" onClick={()=>p.setTransitions((v:any)=>v.filter((x:any)=>x.id!==t.id))}><Trash2 size={14}/></button></div><div className="condition-grid-v13"><label><span>الحقل</span><select value={t.condition?.source||''} onChange={e=>p.updateCondition(t.id,{...(t.condition||{}),source:e.target.value,value:''})}><option value="">اختر الحقل أو السؤال</option>{p.sourceOptions.map((x:any)=><option key={x.key} value={x.key}>{x.group} · {x.label}</option>)}</select></label><label><span>القيمة</span>{(()=>{if(['is_true','is_false'].includes(t.condition?.operator))return <select value={t.condition.operator} onChange={e=>p.updateCondition(t.id,{...(t.condition||{}),operator:e.target.value,value:''})}><option value="is_true">نعم</option><option value="is_false">لا</option></select>;if(o?.type==='boolean'||o?.type==='yes_no')return <select value={t.condition?.value??''} onChange={e=>p.updateCondition(t.id,{...(t.condition||{}),operator:'equals',value:e.target.value})}><option value="">اختر القيمة</option><option value="true">نعم</option><option value="false">لا</option></select>;if(o?.options?.length)return <select value={t.condition?.value??''} onChange={e=>p.updateCondition(t.id,{...(t.condition||{}),operator:'equals',value:e.target.value})}><option value="">اختر القيمة</option>{o.options.map((x:any,i:number)=><option key={i} value={optionValue(x)}>{optionLabel(x)}</option>)}</select>;return <input value={t.condition?.value??''} onChange={e=>p.updateCondition(t.id,{...(t.condition||{}),operator:'equals',value:e.target.value})} placeholder="اكتب القيمة"/>})()}</label><label><span>الأثر</span><select value={t.action} onChange={e=>{const action=e.target.value;const defaultTarget=action==='next'?p.next?.id:null;p.setTransitions((v:any)=>v.map((x:any)=>x.id===t.id?{...x,action,toStageId:defaultTarget}:x))}}>{Object.entries(effectLabels).map(([k,v])=><option key={k} value={k}>{String(v)}</option>)}</select></label>{!terminal&&<label><span>{t.action==='return'?'إرجاع إلى':'المرحلة'}</span><select value={t.toStageId||''} onChange={e=>p.setTransitions((v:any)=>v.map((x:any)=>x.id===t.id?{...x,toStageId:e.target.value||null}:x))}><option value="">اختر المرحلة</option>{p.stages.filter((s:any)=>s.id!==p.currentStage.id&&(t.action!=='return'||s.stageOrder<p.currentStage.stageOrder)).map((s:any)=><option key={s.id} value={s.id}>{s.stageOrder}. {s.nameAr}</option>)}</select></label>}</div><div className="condition-summary-v13"><span>إذا <strong>{o?.label||'الحقل'}</strong> = <strong>{['is_true','is_false'].includes(t.condition?.operator)?(t.condition.operator==='is_true'?'نعم':'لا'):(t.condition?.value||'القيمة')}</strong></span><b>←</b><span>{terminal?effectLabels[t.action]:`${effectLabels[t.action]} ${p.stages.find((s:any)=>s.id===t.toStageId)?.nameAr||'—'}`}</span></div></div>}

function ValidationSection(p:any){return <div className="editor-section-v13"><SectionIntro number="04" title="التحقق والمعاينة" text="قبل النشر، نتحقق من أن كل مرحلة وكل شرط قابل للتنفيذ. الأخطاء الحمراء تمنع النشر."/><div className="validation-grid-v13"><section className="form-card-v13"><div className="validation-score-v13"><div className="score-ring-v13"><strong>{p.allIssues.length?String(p.allIssues.length):'✓'}</strong><span>{p.allIssues.length?'مشكلات تحتاج مراجعة':'جاهز'}</span></div><div><h3>{p.allIssues.length?'نحتاج بعض التعديلات':'القالب جاهز للمراجعة'}</h3><p>{p.allIssues.length?'اضغط على المشكلة للانتقال إلى المكان المرتبط بها.':'يمكنك الآن معاينة تجربة المستخدم أو تشغيل اختبار كامل قبل النشر.'}</p></div></div>{p.allIssues.length===0?<div className="valid-state-v13"><Check size={20}/><div><strong>لا توجد أخطاء بنيوية حالية</strong><span>احفظ المسودة ثم افتح المعاينة أو بيئة الاختبار للتأكد من المسارات.</span></div></div>:<div className="issue-list-v13">{p.allIssues.map((x:any,i:number)=><button key={i} className={`issue-item-v13 ${x.level}`} onClick={()=>{p.setSection(x.section);if(x.stageId)p.setActiveStageId(x.stageId)}}><span className="issue-dot">{x.level==='warning'?'!':'×'}</span><div><strong>{x.title}</strong><small>{x.detail}</small></div><ChevronLeft size={15}/></button>)}</div>}</section><section className="form-card-v13 preview-card-v13"><div className="subhead-v13"><div><span>معاينة واجهة المستخدم</span><strong>كيف سيشاهد مقدم الطلب المعاملة؟</strong><p>المعاينة لا تنفذ المسار ولا تنشئ سجلًا.</p></div><Eye size={20}/></div><div className="preview-frame-v13"><div className="preview-header-v13"><span>طلب جديد</span><strong>{p.typeForm.nameAr||'اسم المعاملة'}</strong></div><div className="preview-profile-v13"><div className="avatar-v13">م</div><div><strong>بيانات مقدم الطلب</strong><span>تأتي معلومات الموظف من النظام تلقائيًا.</span></div></div><div className="preview-line-v13"><span>العناصر</span><b>{p.requesterFields.length}</b></div><div className="preview-line-v13"><span>الأسئلة والقرارات</span><b>{p.requesterQuestions.length}</b></div><div className="preview-stages-v13">{p.stages.map((s:any)=><span key={s.id}><b>{s.stageOrder}</b>{s.nameAr}</span>)}</div></div></section></div><div className="validation-actions-v13"><Link className="btn secondary" to={`/platform/workflows/test/${p.typeId}`}><PlayCircle size={16}/>اختبار سير العمل</Link><button className="btn primary" onClick={()=>p.setSection('publish')} disabled={p.allIssues.length>0}>انتقل إلى النشر <ChevronLeft size={15}/></button></div></div>}

function PublishSection(p:any){return <div className="editor-section-v13"><SectionIntro number="05" title="النشر للشركات" text="النشر ينسخ القالب إلى الشركات كنسخة مستقلة. تعديل شركة لا يغيّر القالب ولا الشركات الأخرى."/><div className="publish-hero-v13"><div><span>النسخة الحالية</span><strong>{p.typeForm.nameAr}</strong><p>المصدر: قالب المنصة · الإصدار الذي سيُنسخ إلى الشركة.</p></div><div className="version-badge-v13">{p.workflowStatus==='active'?'نسخة نشطة':'مسودة'}</div></div><div className="company-publish-grid-v13">{p.companies.map((c:any)=><label key={c.id} className={`company-choice-v13 ${p.publishSelection.includes(c.id)?'selected':''}`}><input type="checkbox" checked={p.publishSelection.includes(c.id)} onChange={e=>p.setPublishSelection((v:string[])=>e.target.checked?[...v,c.id]:v.filter(x=>x!==c.id))}/><div className="company-mark-v13">{(c.display_name||'ش').slice(0,1)}</div><div><strong>{c.display_name}</strong><span>{c.company_identifier}</span></div><Check size={16}/></label>)}</div><div className="publish-note-v13"><Copy size={18}/><div><strong>نسخة مستقلة لكل شركة</strong><span>إذا نشرت v3 إلى شركتين، ثم عدلت شركة واحدة وأصبحت v4، تبقى الأخرى على v3 ويظل قالب المنصة كما هو.</span></div></div><div className="publish-actions-v13"><button className="btn secondary" onClick={p.activate} disabled={p.busy}>تفعيل مسودة القالب</button><button className="btn primary" onClick={p.publishNow} disabled={p.busy||!p.publishSelection.length}><Send size={16}/>نشر إلى {p.publishSelection.length||''} شركة</button></div></div>}

function PublishModal(p:any){return <div className="studio-modal-backdrop"><div className="studio-modal"><div className="modal-head-v13"><div><span>النشر للشركات</span><h3>{p.typeForm.nameAr}</h3></div><button className="icon-btn" onClick={()=>p.setPublishOpen(false)}><X size={16}/></button></div><p className="modal-copy-v13">اختر الشركات التي تريد إنشاء نسخة مستقلة من القالب فيها.</p><div className="modal-company-list-v13">{p.companies.map((c:any)=><label key={c.id}><input type="checkbox" checked={p.publishSelection.includes(c.id)} onChange={e=>p.setPublishSelection((v:string[])=>e.target.checked?[...v,c.id]:v.filter(x=>x!==c.id))}/><span>{c.display_name}</span><small>{c.company_identifier}</small></label>)}</div><div className="modal-actions-v13"><button className="btn secondary" onClick={()=>p.setPublishOpen(false)}>إلغاء</button><button className="btn primary" disabled={!p.publishSelection.length||p.busy} onClick={p.publishNow}>نشر النسخة</button></div></div></div>}

function SectionIntro({number,title,text}:{number:string;title:string;text:string}){return <div className="section-intro-v13"><span>{number}</span><div><h2>{title}</h2><p>{text}</p></div></div>}
function BuilderPanel({title,description,addLabel,onAdd,children,icon}:{title:string;description:string;addLabel:string;onAdd:()=>void;children:any;icon?:any}){return <section className="builder-panel-v13"><div className="builder-panel-head-v13"><div><h3>{title}</h3><p>{description}</p></div><button className="btn secondary" onClick={onAdd}>{icon||<Plus size={15}/>} {addLabel}</button></div>{children}</section>}
function EmptyBuilder({title,text,action,onClick}:{title:string;text:string;action:string;onClick:()=>void}){return <div className="empty-builder-v13"><div className="empty-icon-v13"><LayoutTemplate size={20}/></div><strong>{title}</strong><span>{text}</span><button className="btn secondary" onClick={onClick}><Plus size={14}/>{action}</button></div>}
